    'auth.security.encrypted_session': 'ಎನ್‌ಕ್ರಿಪ್ಟ್ ಮಾಡಿದ ಸೆಷನ್\n||\nSIH ಪ್ರೋಟೋಕಾಲ್\n||\nರೈತರ ಪ್ರವೇಶ\n||\nಖರೀದಿದಾರರ ಪ್ರವೇಶ\n||\nಟ್ರಾನ್ಸ್ಪೋರ್ಟರ್ ಪ್ರವೇಶ\n||\nಪಾತ್ರ-ಆಧಾರಿತ ಪ್ರವೇಶ ನಿಯಂತ್ರಣ\n||\nಹತ್ತಿರದ ಬೇಡಿಕೆಯನ್ನು ಅನ್ವೇಷಿಸಿ\n||\nವಾಣಿಜ್ಯ ಖರೀದಿದಾರರು ಮತ್ತು APMC ಗಳಿಂದ ನೇರ ಸಂಗ್ರಹಣೆ ಆದೇಶಗಳನ್ನು ಪ್ರವೇಶಿಸಿ.\n||\nಸಮರ್ಥ ಲಾಜಿಸ್ಟಿಕ್ಸ್ ಅನ್ನು ಹುಡುಕಿ\n||\nಸಾರಿಗೆ ವೆಚ್ಚವನ್ನು ಕಡಿತಗೊಳಿಸಲು ಗ್ರಾಮೀಣ ಮಿನಿ-ಟ್ರಕ್‌ಗಳಲ್ಲಿ ಸಾಮರ್ಥ್ಯ ಹಂಚಿಕೊಂಡಿದೆ.\n||\nನಿಮ್ಮ ವಿತರಣೆಗಳನ್ನು ಟ್ರ್ಯಾಕ್ ಮಾಡಿ\n||\nನೈಜ-ಸಮಯದ ರವಾನೆ ನವೀಕರಣಗಳು ಮತ್ತು ನೇರ ಪಾವತಿಯ ಪರಿಹಾರವನ್ನು ಸ್ವೀಕರಿಸಿ.\n||\nನೇರ ಫಾರ್ಮ್ ಸೋರ್ಸಿಂಗ್\n||\nಪಾರದರ್ಶಕ ಸುಗ್ಗಿಯ ಸಮಯಾವಧಿಯೊಂದಿಗೆ ಪರಿಶೀಲಿಸಿದ ಪ್ರಾದೇಶಿಕ ರೈತ ಸಮೂಹಗಳೊಂದಿಗೆ ಸಂಪರ್ಕ ಸಾಧಿಸಿ.\n||\nಬ್ರಾಡ್‌ಕಾಸ್ಟ್ ಸಂಗ್ರಹಣೆಯ ಬೇಡಿಕೆ\n||\nಹೊಂದಾಣಿಕೆಯ ಕೃಷಿ ಉತ್ಪನ್ನಗಳನ್ನು ಕಂಡುಹಿಡಿಯಲು ಅಗತ್ಯವಿರುವ ಪ್ರಮಾಣಗಳು ಮತ್ತು ಗುರಿ ಬೆಲೆಗಳನ್ನು ಪೋಸ್ಟ್ ಮಾಡಿ.\n||\nಪರಿಶೀಲಿಸಿದ ಸಾಗಣೆ ಟ್ರ್ಯಾಕಿಂಗ್\n||\nಗ್ರಾಮೀಣ ಫಾರ್ಮ್-ಗೇಟ್ ಪಿಕಪ್‌ಗಳಿಂದ ನಿಮ್ಮ ಗೋದಾಮಿಗೆ ಒಳಬರುವ ಸರಕು ಸಾಗಣೆಯನ್ನು ಮೇಲ್ವಿಚಾರಣೆ ಮಾಡಿ.\n||\nಖಾಲಿ ರಿಟರ್ನ್ ಟ್ರಿಪ್‌ಗಳನ್ನು ಭರ್ತಿ ಮಾಡಿ\n||\nನಿಮ್ಮ ಟ್ರಕ್ ಸಾಮರ್ಥ್ಯಕ್ಕೆ ಹೊಂದಿಕೆಯಾಗುವ ಆನ್-ರೂಟ್ ಫಾರ್ಮ್ ಪಿಕಪ್‌ಗಳಿಗಾಗಿ ಸೂಚನೆ ಪಡೆಯಿರಿ.\n||\nನೇರ ಸಾಗಣೆದಾರರ ಪಾವತಿ\n||\nಪಾರದರ್ಶಕ ಪ್ರಯಾಣ ದರಗಳನ್ನು ನೇರವಾಗಿ ನಿಮ್ಮ ಪರಿಶೀಲಿಸಿದ ಬ್ಯಾಂಕ್ ಖಾತೆಗೆ ಜಮಾ ಮಾಡಲಾಗಿದೆ.\n||\nನಿಮ್ಮ ವಾಹನ ಫ್ಲೀಟ್ ಅನ್ನು ನಿರ್ವಹಿಸಿ\n||\nವಾಹನಗಳನ್ನು ನೋಂದಾಯಿಸಿ, ಟ್ರ್ಯಾಕ್ ನಿರ್ವಹಣೆ ಮತ್ತು ಸಾಮರ್ಥ್ಯ-ಹೊಂದಾಣಿಕೆಯ ಪ್ರವಾಸಗಳನ್ನು ಸ್ವೀಕರಿಸಿ.\n||\nರೈತ ಪಾಲುದಾರ',
