    'auth.buyer.partner_title': 'ವಾಣಿಜ್ಯ ಖರೀದಿದಾರ\n||\nಟ್ರಾನ್ಸ್ಪೋರ್ಟರ್ ಫ್ಲೀಟ್ ಪಾಲುದಾರ\n||\nಖಾತೆಯನ್ನು ರಚಿಸಲಾಗುತ್ತಿದೆ...\n||\nಸಂಪೂರ್ಣ ನೋಂದಣಿ\n||\nನೋಂದಾಯಿಸಲಾಗುತ್ತಿದೆ...\n||\nಸಂಪೂರ್ಣ ಖರೀದಿದಾರ ನೋಂದಣಿ\n||\nಸಂಪೂರ್ಣ ಟ್ರಾನ್ಸ್ಪೋರ್ಟರ್ ನೋಂದಣಿ\n||\nಕೃಷಿ ಕಾರ್ಯಾಚರಣೆಗಳ ಅವಲೋಕನ, ಲಾಜಿಸ್ಟಿಕ್ಸ್ ಸ್ಥಿತಿ ಮತ್ತು ಪ್ರಾದೇಶಿಕ ಮಂಡಿ ಬೇಡಿಕೆ.\n||\nಸಂಗ್ರಹಣೆ ಕಾರ್ಯಾಚರಣೆಗಳು\n||\nಬೃಹತ್ ಕೃಷಿ ಬೆಳೆ ಸಂಗ್ರಹಣೆ ವಿನಂತಿಗಳು, ಒಳಬರುವ ವಿತರಣೆಗಳು ಮತ್ತು ಸಗಟು ಬೇಡಿಕೆಯನ್ನು ನಿರ್ವಹಿಸಿ.\n||\nಟ್ರಾನ್ಸ್ಪೋರ್ಟರ್ ರವಾನೆ ನಿಯಂತ್ರಣ\n||\nಫ್ಲೀಟ್ ಕಾರ್ಯಾಚರಣೆಗಳ ಅವಲೋಕನ, ಹತ್ತಿರದ ಫಾರ್ಮ್ ಪಿಕಪ್ ಲೋಡ್‌ಗಳು ಮತ್ತು ವಾಹನ ನಿರ್ವಹಣೆ.\n||\nಅಂದಾಜು. ಮೌಲ್ಯ\n||\nಕ್ಯಾಟಲಾಗ್‌ನಲ್ಲಿ ಪಟ್ಟಿ ಮಾಡಲಾಗಿದೆ\n||\nಸಾರಿಗೆಯಲ್ಲಿ / ನಿಯೋಜಿಸಲಾಗಿದೆ\n||\nವಾಹನಗಳ ಹುಡುಕಾಟ\n||\nಸಕ್ರಿಯ ಕ್ಯಾಟಲಾಗ್ ಅನ್ನು ಆಧರಿಸಿದೆ\n||\nಸಕ್ರಿಯ ಸಂಗ್ರಹಣೆಗಳು\n||\nಆದೇಶಗಳನ್ನು ತೆರೆಯಿರಿ\n||\nಒಳಬರುವ ವಿತರಣೆಗಳು\n||\nಬದ್ಧ ಪರಿಮಾಣ\n||\nಸೋರ್ಸಿಂಗ್ / ಪೂರೈಸುವಲ್ಲಿ\n||\nರೈತರ ಪಂದ್ಯಕ್ಕಾಗಿ ಕಾಯಲಾಗುತ್ತಿದೆ\n||\nಗಮ್ಯಸ್ಥಾನಕ್ಕೆ ಸಾಗಣೆಯಲ್ಲಿ\n||\nನೇರ ಸಂಗ್ರಹಣೆ ವೆಚ್ಚ',
